    println!("{}", gcd(252, 105));
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 {
        False
    } else if n <= 3 {
        True
    } else if n % 2 == 0 || n % 3 == 0 {
        False
    } else {
        let mut i = 5
        while i * i <= n {
            if n % i == 0 || n % (i + 2) == 0 {
                return False
            }
            i = i + 6
        }
        True
    }
}

